<?php
/** Assets → Logistics. Single-shipment-first staff workflow. */
session_start();
require_once '../../config.php';
require_once '../../includes/functions.php';
require_once '../../includes/i18n.php';
require_once '../../includes/theme.php';
require_once '../../includes/tenancy.php';
require_once '../../includes/rbac.php';
require_once '../../includes/capabilities.php';
require_once '../../includes/service_context.php';
require_once '../../includes/services/asset_logistics.php';
I18n::initFromSession();
requireModuleAccess('assets');
$conn = connectToDatabase();
requireCapability(Cap::ASSETS_LOGISTICS, $conn);
$ctx = ActorContext::fromSession($conn);
$tenantId = getActiveTenantId($conn, (int)($_SESSION['analyst_id'] ?? 0));
if (!$tenantId) $tenantId = getDefaultTenantId($conn);
$purposes = [
    'outbound_dispatch' => AssetLogisticsService::listPurposes($conn, $ctx, (int)$tenantId, 'outbound_dispatch'),
    'inbound_return' => AssetLogisticsService::listPurposes($conn, $ctx, (int)$tenantId, 'inbound_return'),
];
$assetSql = 'SELECT id, hostname, asset_tag FROM assets';
$args = [];
if (!isActiveTenantAll($conn)) {
    $defaultTenant = getDefaultTenantId($conn);
    if ((int)$tenantId === (int)$defaultTenant) {
        $assetSql .= ' WHERE tenant_id IS NULL OR tenant_id = ?';
        $args[] = $defaultTenant;
    } else {
        $assetSql .= ' WHERE tenant_id = ?';
        $args[] = $tenantId;
    }
}
$assetSql .= ' ORDER BY COALESCE(asset_tag, hostname), id LIMIT 1000';
$assetStmt = $conn->prepare($assetSql);
$assetStmt->execute($args);
$assets = $assetStmt->fetchAll(PDO::FETCH_ASSOC);
$userSql = 'SELECT id, display_name, email FROM users WHERE is_active = 1';
$userArgs = [];
if (!isActiveTenantAll($conn)) {
    $defaultTenant = getDefaultTenantId($conn);
    if ((int)$tenantId === (int)$defaultTenant) {
        $userSql .= ' AND (tenant_id IS NULL OR tenant_id = ?)';
        $userArgs[] = $defaultTenant;
    } else {
        $userSql .= ' AND tenant_id = ?';
        $userArgs[] = $tenantId;
    }
}
$userSql .= " ORDER BY COALESCE(NULLIF(display_name, ''), email), id LIMIT 1000";
$userStmt = $conn->prepare($userSql);
$userStmt->execute($userArgs);
$portalRecipients = $userStmt->fetchAll(PDO::FETCH_ASSOC);

$costCentreSql = 'SELECT id, code, name FROM cost_centres WHERE is_active = 1';
$costCentreArgs = [];
if (!isActiveTenantAll($conn)) {
    $costCentreSql .= ' AND tenant_id = ?';
    $costCentreArgs[] = (int)$tenantId;
}
$costCentreSql .= ' ORDER BY code, name, id';
$costCentreStmt = $conn->prepare($costCentreSql);
$costCentreStmt->execute($costCentreArgs);
$costCentres = $costCentreStmt->fetchAll(PDO::FETCH_ASSOC);
$current_page = 'logistics';
$path_prefix = '../../';
$translationNamespaces = ['common', 'asset-management'];
?>
