window.logisticsCostCentres = <?php echo json_encode($costCentres, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE); ?>;</script>
<style>
.lgx-wrap{padding:20px;max-width:1400px;margin:0 auto;color:var(--text)}.lgx-grid{display:grid;grid-template-columns:minmax(300px,1fr) minmax(360px,1.2fr);gap:16px}.lgx-card{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:18px;min-width:0}.lgx-card h2{font-size:18px;margin:0 0 14px}.lgx-field{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}.lgx-field label{font-weight:600;font-size:13px}.lgx-field input,.lgx-field select,.lgx-field textarea{background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:9px;font:inherit}.lgx-field select[multiple]{min-height:180px}.lgx-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.lgx-actions{display:flex;gap:8px;flex-wrap:wrap}.lgx-muted{color:var(--text-muted,var(--text-secondary,#666));font-size:13px}.lgx-result{white-space:pre-wrap;margin:12px 0;padding:10px;border-radius:6px;background:var(--surface-2,var(--surface));border:1px solid var(--border);min-height:22px}.lgx-table{width:100%;border-collapse:collapse}.lgx-table td,.lgx-table th{text-align:left;padding:8px;border-bottom:1px solid var(--border);vertical-align:top}.lgx-shipment{border:1px solid var(--border);border-radius:8px;padding:12px;margin:10px 0}.lgx-assets{display:flex;flex-wrap:wrap;gap:6px}.lgx-chip{background:var(--surface-2,var(--surface));border:1px solid var(--border);padding:3px 7px;border-radius:14px;font-size:12px}@media(max-width:850px){.lgx-grid{grid-template-columns:1fr}.lgx-row{grid-template-columns:1fr}}
