<main class="lgx-wrap">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px"><div><h1 style="margin:0 0 4px"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.title')); ?></h1><div class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.dispatches_returns_tracking')); ?></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="btn btn-secondary" href="settings.php"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_title')); ?></a><a class="btn btn-secondary" href="../index.php"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.back_to_assets')); ?></a></div></div>
  <div class="lgx-grid">
    <section class="lgx-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.new_movement')); ?></h2>
      <form id="lgxCreate">
        <div class="lgx-field"><label for="lgxType"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.movement_type_label')); ?></label><select id="lgxType" name="movement_type"><option value="outbound_dispatch"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.outbound_dispatch')); ?></option><option value="inbound_return"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.inbound_return')); ?></option></select></div>
        <div class="lgx-field"><label for="lgxPurpose"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.purpose_label_plain')); ?></label><select id="lgxPurpose" name="purpose_id" required></select></div>
        <div class="lgx-field"><label for="lgxAssets"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.assets')); ?> <span class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.select_one_or_more')); ?></span></label><input type="search" id="lgxAssetSearch" class="form-input" autocomplete="off" placeholder="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.search_assets')); ?>"><select id="lgxAssets" name="asset_ids" multiple required><?php foreach ($assets as $a): $label = trim((string)($a['asset_tag'] ?? '')) ?: trim((string)($a['hostname'] ?? '')) ?: ('Asset #' . $a['id']); ?><option value="<?php echo (int)$a['id']; ?>"><?php echo htmlspecialchars($label . ' — #' . $a['id']); ?></option><?php endforeach; ?></select><div class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.assets_limit_hint')); ?></div></div>
        <div class="lgx-field" id="lgxRecipientWrap"><label for="lgxRecipient"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.recipient')); ?></label><input type="search" id="lgxRecipientSearch" class="form-input" autocomplete="off" placeholder="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.search_recipients')); ?>"><select id="lgxRecipient" name="recipient_user_id"><option value=""><?php echo htmlspecialchars(I18n::t('asset-management.logistics.no_recipient')); ?></option><?php foreach ($portalRecipients as $u): $personLabel = trim((string)($u['display_name'] ?? '')) ?: trim((string)($u['email'] ?? '')) ?: ('Portal user #' . $u['id']); ?><option value="<?php echo (int)$u['id']; ?>"><?php echo htmlspecialchars($personLabel . ' — #' . $u['id']); ?></option><?php endforeach; ?></select><div class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.return_recipient_hint')); ?></div></div>
        <div class="lgx-field"><label for="lgxCarrier"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.carrier_label')); ?></label><select id="lgxCarrier" name="carrier_supplier_id"><option value=""><?php echo htmlspecialchars(I18n::t('asset-management.logistics.no_carrier_selected')); ?></option></select><div class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.carrier_default_hint')); ?></div></div>
        <div class="lgx-field"><label for="lgxCostCentre"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.movement_cost_centre')); ?></label><select id="lgxCostCentre" name="cost_centre_id"><option value=""><?php echo htmlspecialchars(I18n::t('asset-management.logistics.cost_centre_placeholder')); ?></option><?php foreach ($costCentres as $cc): $ccLabel = trim((string)($cc['code'] ?? '')); $ccName = trim((string)($cc['name'] ?? '')); ?><option value="<?php echo (int)$cc['id']; ?>"><?php echo htmlspecialchars(($ccLabel !== '' ? $ccLabel . ' — ' : '') . $ccName); ?></option><?php endforeach; ?></select><div class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.cost_centre_hint')); ?></div></div>
        <div class="lgx-field"><label for="lgxNotes"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.notes_optional')); ?></label><textarea id="lgxNotes" name="notes" rows="2" maxlength="10000"></textarea></div>
        <button class="btn btn-primary" type="submit"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.create_movement')); ?></button>
      </form>
