    <section class="lgx-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.open_movement')); ?></h2><form id="lgxLoad"><div class="lgx-row"><div class="lgx-field"><label for="lgxMovementId"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.movement_id')); ?></label><input id="lgxMovementId" type="number" min="1" required></div><div class="lgx-field" style="justify-content:end"><button class="btn btn-secondary" type="submit"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.load_movement')); ?></button></div></div></form><div id="lgxDetail" class="lgx-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.create_or_enter_movement')); ?></div></section>
  </div>
