<script>
(function(){
 const tr=(key)=>((window.translations||{})['asset-management']||{}).logistics?.[key]||key;
 const api='../../api/assets/logistics.php';
 const purposes=<?php echo json_encode($purposes, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;
 const recipients=<?php echo json_encode(array_map(static function($u){ return ['id'=>(int)$u['id'],'label'=>(trim((string)($u['display_name'] ?? '')) ?: trim((string)($u['email'] ?? '')) ?: ('Portal user #' . $u['id'])) . ' — #' . (int)$u['id']]; }, $portalRecipients), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?>;
 const type=document.getElementById('lgxType'), purpose=document.getElementById('lgxPurpose'), detail=document.getElementById('lgxDetail'), message=document.getElementById('lgxMessage');
 let current=null;
 function say(text,error=false){message.hidden=false;message.textContent=text;message.style.borderColor=error?'var(--danger,#c33)':'var(--border)';}
 function statusText(s){const key=String(s||'').toLowerCase(),label=tr(key);return label===key?key.replaceAll('_',' '):label;}
 function eventText(s){const key='event_'+String(s||'').toLowerCase();return tr(key)!==key?tr(key):String(s||'').replaceAll('_',' ');}
 function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function refreshPurposes(){const list=purposes[type.value]||[];purpose.innerHTML=list.map(p=>'<option value="'+Number(p.id)+'">'+esc(p.name)+'</option>').join('');if(!list.length)purpose.innerHTML='<option value="">'+tr('configure_active_purpose')+'</option>';}
 const recipientWrap=document.getElementById('lgxRecipientWrap'), recipient=document.getElementById('lgxRecipient');
 function filterOptions(inputId, selectId){const input=document.getElementById(inputId),select=document.getElementById(selectId);if(!input||!select)return;input.addEventListener('input',()=>{const q=input.value.trim().toLocaleLowerCase();Array.from(select.options).forEach(o=>{if(!o.value){o.hidden=false;return;}o.hidden=q!==''&&!o.text.toLocaleLowerCase().includes(q);});});}
 filterOptions('lgxAssetSearch','lgxAssets');filterOptions('lgxRecipientSearch','lgxRecipient');
 function refreshRecipient(){recipientWrap.hidden=false;recipientWrap.querySelector('label').textContent=type.value==='outbound_dispatch'?tr('delivery_recipient'):tr('employee_returning_asset');recipientWrap.querySelector('.lgx-muted').textContent=type.value==='outbound_dispatch'?tr('outbound_recipient_hint'):tr('return_recipient_hint');}
 type.addEventListener('change',refreshPurposes);type.addEventListener('change',refreshRecipient);refreshPurposes();refreshRecipient();
 async function request(action,data){const r=await fetch(api,{method:action?'POST':'GET',credentials:'same-origin',headers:action?{'Content-Type':'application/json'}:{},body:action?JSON.stringify(Object.assign({action},data||{})):undefined});let j;try{j=await r.json()}catch(e){throw new Error(tr('unexpected_server_response'));}if(!r.ok||!j.success)throw new Error(j.error||tr('request_failed'));return j;}
 const carrierConfigPromise=request('list_carriers').then(c=>{window.logisticsCarriers=c.carriers||[];const sel=document.getElementById('lgxCarrier');sel.innerHTML='<option value="">'+tr('no_carrier_selected')+'</option>'+window.logisticsCarriers.map(c=>'<option value="'+Number(c.supplier_id)+'" '+(Number(c.is_default)?'selected':'')+'>'+esc(c.name)+(Number(c.is_default)?' · '+tr('default_carrier'):'')+'</option>').join('');}).catch(e=>{console.error('Could not load carrier settings',e);});
 document.getElementById('lgxCreate').addEventListener('submit',async e=>{e.preventDefault();const ids=Array.from(document.getElementById('lgxAssets').selectedOptions).map(o=>Number(o.value));if(!ids.length){say(tr('select_at_least_one_asset'),true);return;}if(!purpose.value){say(tr('configure_active_purpose'),true);return;}const cc=document.getElementById('lgxCostCentre').value;const data={movement_type:type.value,purpose_id:Number(purpose.value),asset_ids:ids,notes:document.getElementById('lgxNotes').value};const carrier=document.getElementById('lgxCarrier').value;if(carrier!=='')data.carrier_supplier_id=Number(carrier);if(cc!=='')data.cost_centre_id=Number(cc);if(type.value==='inbound_return'&&recipient.value===''){say(tr('select_return_employee'),true);return;}if(recipient.value!=='')data.recipient_user_id=Number(recipient.value);try{const r=await request('create_movement',data);document.getElementById('lgxMovementId').value=r.movement_id;say(tr('movement_created_prefix')+r.movement_id+tr('movement_created_middle')+r.shipment_number+'.');await load(r.movement_id);}catch(err){say(err.message,true);}});
 document.getElementById('lgxLoad').addEventListener('submit',e=>{e.preventDefault();load(Number(document.getElementById('lgxMovementId').value));});
 async function load(id){return loadMovement(id);}
 async function loadMovement(id){try{await carrierConfigPromise;const r=await fetch(api+'?movement_id='+encodeURIComponent(id),{credentials:'same-origin'});const j=await r.json();if(!r.ok||!j.success)throw new Error(j.error||tr('could_not_load_movement'));current=j;render(j);say(tr('loaded_movement_prefix')+id+'.');}catch(e){detail.textContent=e.message;say(e.message,true);}}
 function render(j){const m=j.movement, assets=j.assets||[], ships=j.shipments||[], events=j.events||[], policy=j.policy||{};let h='<h3 style="margin:8px 0">'+tr('movement_label_prefix')+Number(m.id)+' · '+esc(m.movement_type==='outbound_dispatch'?tr('outbound_dispatch'):tr('inbound_return'))+'</h3><p class="lgx-muted">'+tr('purpose_label_prefix')+''+esc(m.purpose_name||'—')+' · '+tr('status_label')+' '+esc(statusText(m.status))+' · '+tr('cost_centre_label')+' '+esc(m.cost_centre_id||tr('not_set'))+'</p>'+(m.status==='in_progress'?'<button type="button" class="btn btn-secondary" id="lgxCloseMovement">'+tr('close_movement')+'</button>':'');
 ships.forEach(s=>{const sa=assets.filter(a=>Number(a.shipment_id)===Number(s.id));h+='<div class="lgx-shipment"><strong>'+tr('shipment_number_prefix')+Number(s.shipment_number)+'</strong> <span class="lgx-chip">'+esc(statusText(s.status))+'</span><div class="lgx-assets" style="margin:8px 0">'+sa.map(a=>'<span class="lgx-chip">'+esc(a.asset_tag_snapshot||a.hostname_snapshot||('Asset #'+a.asset_id))+'</span>').join('')+'</div><form class="lgxTrack" data-id="'+Number(s.id)+'">'+(m.movement_type==='outbound_dispatch'?'<div class="lgx-field"><label>'+tr('delivery_recipient')+'</label><select name="recipient_user_id" '+(String(s.tracking_number||'').trim()?'disabled':'')+'><option value="">'+tr('no_recipient')+'</option>'+recipients.map(u=>'<option value="'+Number(u.id)+'" '+(Number(s.recipient_user_id)===Number(u.id)?'selected':'')+'>'+esc(u.label)+'</option>').join('')+'</select>'+(String(s.tracking_number||'').trim()?'<span class="lgx-muted">'+tr('recipient_locked_after_awb')+'</span>':'')+'</div>':'')+'<div class="lgx-row"><div class="lgx-field"><label>'+tr('transport_mode_label')+'</label><select name="transport_mode" '+(String(s.tracking_number||'').trim()?'disabled':'')+'><option value="air" '+((s.transport_mode||'surface')==='air'?'selected':'')+'>'+tr('transport_air')+'</option><option value="surface" '+((s.transport_mode||'surface')==='surface'?'selected':'')+'>'+tr('transport_surface')+'</option></select></div><div class="lgx-field"><label>'+tr('carrier_label')+'</label><select name="carrier_supplier_id" '+(String(s.tracking_number||'').trim()?'disabled':'')+'><option value="">'+tr('choose')+'</option>'+((window.logisticsCarriers||[]).filter(c=>Number(c.carrier_active)===1).sort((a,b)=>Number(b.is_default)-Number(a.is_default)).map(c=>'<option value="'+Number(c.supplier_id)+'" '+(Number(s.carrier_supplier_id)===Number(c.supplier_id)?'selected':'')+'>'+esc(c.name)+(Number(c.is_default)?' · default':'')+'</option>').join(''))+'</select></div><div class="lgx-field"><label>'+tr('manual_carrier_label')+'</label><input name="carrier_name" maxlength="150" value="'+esc(s.carrier_name||'')+'" '+(String(s.tracking_number||'').trim()?'disabled':'')+' placeholder="'+tr('manual_carrier_placeholder')+'"></div><div class="lgx-field"><label>'+tr('tracking_label')+'</label><input name="tracking_number" maxlength="150" value="'+esc(s.tracking_number)+'" '+(String(s.tracking_number||'').trim()?'disabled':'')+' ></div></div>'+(s.tracking_url?'<p><a href="'+esc(s.tracking_url)+'" target="_blank" rel="noopener noreferrer">'+tr('track_shipment')+'</a></p>':'')+'<div class="lgx-field"><label>'+tr('shipment_notes_label')+'</label><input name="notes" maxlength="10000" value="'+esc(s.notes)+'"></div>'+(m.movement_type==='inbound_return'?'<h4>'+tr('return_collection_arrangements')+'</h4><div class="lgx-row"><div class="lgx-field"><label>'+tr('collection_method_label')+'</label><select name="collection_method"><option value="">'+tr('choose')+'</option><option value="home_pickup" '+(s.collection_method==='home_pickup'?'selected':'')+'>'+tr('home_pickup')+'</option><option value="drop_off" '+(s.collection_method==='drop_off'?'selected':'')+'>'+tr('drop_off_point')+'</option></select></div><div class="lgx-field"><label>'+tr('scheduled_collection_label')+'</label><input type="datetime-local" name="pickup_scheduled_at" value="'+esc((s.pickup_scheduled_at||'').replace(' ','T').slice(0,16))+'"></div></div><div class="lgx-field"><label>'+tr('home_pickup_address_label')+'</label><textarea name="pickup_address" rows="2" maxlength="10000">'+esc(s.pickup_address||'')+'</textarea></div><div class="lgx-field"><label>'+tr('dropoff_location_label')+'</label><textarea name="dropoff_location" rows="2" maxlength="10000">'+esc(s.dropoff_location||'')+'</textarea></div><div class="lgx-field"><label>'+tr('employee_instructions_label')+'</label><textarea name="return_instructions" rows="2" maxlength="10000">'+esc(s.return_instructions||'')+'</textarea></div>':'')+'<div class="lgx-row"><div class="lgx-field"><label>'+tr('shipment_cost_centre_override')+'</label><select name="cost_centre_id"><option value="">'+tr('blank_inherit')+'</option>'+(window.logisticsCostCentres||[]).map(cc=>'<option value="'+Number(cc.id)+'" '+(String(s.cost_centre_id||'')===String(cc.id)?'selected':'')+' >'+esc((cc.code?cc.code+' — ':'')+cc.name)+'</option>').join('')+'</select><span class="lgx-muted">'+tr('effective_cost_centre')+' '+esc(s.effective_cost_centre_id||tr('not_set'))+'</span></div><div class="lgx-field" style="justify-content:end"><button class="btn btn-secondary" type="button" data-save-cost-centre="'+Number(s.id)+'">'+tr('save_cost_centre_override')+'</button></div></div><div class="lgx-actions"><button class="btn btn-secondary" type="submit">'+tr('save_tracking')+'</button><label class="lgx-muted">'+tr('advance_status')+' <select name="status"><option value="">'+tr('choose')+'</option>'+['dispatched','in_transit','delivered','exception','cancelled'].map(st=>'<option value="'+st+'">'+statusText(st)+'</option>').join('')+'</select></label>'+(s.status==='pending'&&!String(s.tracking_number||'').trim()?'<button class="btn btn-secondary" type="button" data-split="'+Number(s.id)+'">'+tr('split_shipment')+'</button>':'')+(s.status==='cancelled'&&sa.length?'<button class="btn btn-secondary" type="button" data-replace-shipment="'+Number(s.id)+'">'+tr('create_replacement_shipment')+'</button>':'')+'</div></form></div>';});
 // Receipt inspection is available only after delivery; the service enforces policy and tenant scope.
 ships.forEach(s=>{if(s.status!=='delivered'||policy.post_receipt_action!=='inspection'||policy.inspection_provider!=='manual')return;const sa=assets.filter(a=>Number(a.shipment_id)===Number(s.id));h+='<div class="lgx-shipment"><h4 style="margin:0 0 8px">'+tr('inspection_label')+' — '+tr('shipment_number_prefix')+Number(s.shipment_number)+'</h4><p class="lgx-muted">'+tr('record_outcomes_hint')+'</p><form class="lgxReceipt" data-id="'+Number(s.id)+'"><div class="lgx-field"><label>'+tr('inspection_notes_optional')+'</label><textarea name="notes" rows="2" maxlength="10000"></textarea></div>'+sa.map(a=>'<div class="lgx-row" style="align-items:center"><div>'+esc(a.asset_tag_snapshot||a.hostname_snapshot||('Asset #'+a.asset_id))+'</div><div class="lgx-field"><label>'+tr('inspection_outcome_label')+'</label><select required name="outcome_'+Number(a.asset_id)+'"><option value="">'+tr('choose_outcome')+'</option><option value="passed">Passed</option><option value="minor_wear">Minor wear</option><option value="damaged">Damaged</option><option value="scrap">Scrap</option></select></div></div>').join('')+'<button class="btn btn-secondary" type="submit">'+tr('record_receipt_outcomes')+'</button></form></div>';});
 h+='<h3 style="font-size:15px">'+tr('recent_movement_events')+'</h3><table class="lgx-table"><thead><tr><th>'+tr('movement_event_label')+'</th><th>'+tr('movement_event_change')+'</th><th>'+tr('movement_event_when')+'</th></tr></thead><tbody>'+events.slice(-8).reverse().map(e=>'<tr><td>'+esc(eventText(e.event_type))+'</td><td>'+esc((e.old_value||'—')+' → '+(e.new_value||'—')+(e.notes?' · '+e.notes:''))+'</td><td>'+esc(e.created_datetime||'')+'</td></tr>').join('')+'</tbody></table>';
 detail.innerHTML=h;
 const closeBtn=detail.querySelector('#lgxCloseMovement');if(closeBtn)closeBtn.addEventListener('click',async()=>{if(!confirm(tr('confirm_close_movement')))return;try{await request('close_movement',{movement_id:Number(m.id)});await loadMovement(Number(m.id));say(tr('movement_closed'));}catch(err){say(err.message,true);}});
 detail.querySelectorAll('.lgxTrack').forEach(form=>{const ship=ships.find(x=>Number(x.id)===Number(form.dataset.id));if(ship&&['delivered','cancelled'].includes(ship.status)){form.querySelectorAll('input,select,textarea,button').forEach(el=>{if(!el.matches('[data-replace-shipment]'))el.disabled=true;});}});
 detail.querySelectorAll('.lgxTrack').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form),id=Number(form.dataset.id),ship=ships.find(x=>Number(x.id)===id);if(fd.get('status')==='cancelled'&&((fd.get('tracking_number')||'').trim()||(ship&&String(ship.tracking_number||'').trim()))&&!confirm(tr('confirm_cancel_awb_shipment')))return;try{await request('update_shipment',{shipment_id:id,fields:{...(form.querySelector('[name=carrier_supplier_id]').disabled?{}:{carrier_supplier_id:fd.get('carrier_supplier_id')||null}),...(form.querySelector('[name=carrier_name]').disabled?{}:{carrier_name:fd.get('carrier_name')||null}),...(form.querySelector('[name=transport_mode]').disabled?{}:{transport_mode:fd.get('transport_mode')||'surface'}),...(form.querySelector('[name=tracking_number]').disabled?{}:{tracking_number:fd.get('tracking_number')}),notes:fd.get('notes'),...(form.querySelector('[name=recipient_user_id]')&&!form.querySelector('[name=recipient_user_id]').disabled?{recipient_user_id:fd.get('recipient_user_id')||null}:{}),...(form.querySelector('[name=collection_method]')?{collection_method:fd.get('collection_method')||null,pickup_scheduled_at:fd.get('pickup_scheduled_at')||null,pickup_address:fd.get('pickup_address')||null,dropoff_location:fd.get('dropoff_location')||null,return_instructions:fd.get('return_instructions')||null}:{})}});if(fd.get('status'))await request('transition_shipment',{shipment_id:id,status:fd.get('status')});await loadMovement(Number(m.id));}catch(err){say(err.message,true);}}));
 detail.querySelectorAll('[data-save-cost-centre]').forEach(btn=>btn.addEventListener('click',async()=>{const id=Number(btn.dataset.saveCostCentre),form=btn.closest('form'),field=form.querySelector('[name="cost_centre_id"]'),value=field.value.trim();if(value!==''&&(!Number.isInteger(Number(value))||Number(value)<1)){say(tr('positive_cost_centre_hint'),true);return;}try{await request('set_shipment_cost_centre',{shipment_id:id,cost_centre_id:value===''?null:Number(value)});await loadMovement(Number(m.id));say(tr('cost_centre_saved'));}catch(err){say(err.message,true);}}));
 detail.querySelectorAll('[data-replace-shipment]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm(tr('confirm_replace_cancelled_shipment')))return;try{const result=await request('replace_cancelled_shipment',{shipment_id:Number(btn.dataset.replaceShipment)});await loadMovement(Number(m.id));say(tr('replacement_shipment_created_prefix')+result.shipment_number+'.');}catch(err){say(err.message,true);}}));
 detail.querySelectorAll('.lgxReceipt').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form),outcomes=[];for(const [name,value] of fd.entries()){if(!name.startsWith('outcome_'))continue;if(!value){say(tr('choose_outcome_every_asset'),true);return;}outcomes.push({asset_id:Number(name.slice(8)),outcome_code:String(value)});}try{await request('record_receipt_outcomes',{shipment_id:Number(form.dataset.id),outcomes,notes:fd.get('notes')||''});await loadMovement(Number(m.id));say(tr('receipt_outcomes_recorded'));}catch(err){say(err.message,true);}}));
 detail.querySelectorAll('[data-split]').forEach(btn=>btn.addEventListener('click',()=>showSplit(Number(btn.dataset.split),assets.filter(a=>Number(a.shipment_id)===Number(btn.dataset.split)),Number(m.id))));
 }
 function showSplit(shipmentId,assets,movementId){if(assets.length<2){say(tr('shipment_split_min_assets'),true);return;}const opts=assets.map(a=>'<label style="display:block;margin:6px 0"><input type="checkbox" value="'+Number(a.asset_id)+'"> '+esc(a.asset_tag_snapshot||a.hostname_snapshot||('Asset #'+a.asset_id))+'</label>').join('');const overlay=document.createElement('div');overlay.style.cssText='position:fixed;inset:0;background:#0008;display:grid;place-items:center;z-index:9999;padding:16px';overlay.innerHTML='<div class="lgx-card" style="max-width:460px;width:100%;max-height:80vh;overflow:auto"><h2>'+tr('split_shipment_title').replace('{id}',shipmentId)+'</h2><p class="lgx-muted">'+tr('split_create_help')+'</p>'+opts+'<div class="lgx-actions"><button class="btn btn-primary" id="lgxDoSplit">'+tr('create_shipment')+'</button><button class="btn btn-secondary" id="lgxCancelSplit">'+tr('cancel')+'</button></div></div>';document.body.appendChild(overlay);overlay.querySelector('#lgxCancelSplit').onclick=()=>overlay.remove();overlay.querySelector('#lgxDoSplit').onclick=async()=>{const ids=Array.from(overlay.querySelectorAll('input:checked')).map(i=>Number(i.value));if(!ids.length||ids.length>=assets.length){say(tr('select_some_not_all'),true);return;}try{await request('split_shipment',{shipment_id:shipmentId,asset_ids:ids});overlay.remove();await loadMovement(movementId);say(tr('shipment_split_completed'));}catch(e){say(e.message,true);}};}
})();
</script>
</body></html>
